check:
{v:'VER',what:'behind the scoreboard and how-to pages the live fight can be seen: no floor labels or HUD drawn there, a light blur, the fights at mid height (his Q52/Q54)',
 run:function(){
   if(typeof tskInit!=='function'||typeof hubStationNames!=='function'||typeof drawHubHUD!=='function') return 'missing functions';
